for(const name of['concurrent-local-real-contention-expanded.json','concurrent-local-synthetic-contention.json']){const report=read(name);for(const p of report.profiles){assert.ok(p.readRequests>=100);assert.equal(p.acknowledgedWrites,25);assert.ok(p.p95RoundTripMs<=1000);assert.ok(p.maxSampledRssBytes<=536870912);for(const w of p.writes)assert.ok(w.roundTripMs<=2000);for(const sample of p.reads)if(sample.method==='getChangeImpact')assert.ok(sample.roundTripMs<=1000);}}
const sources=['output/concurrent-local/refactored-unit-tests.log','output/concurrent-local/read-mode-full-check-validated-reports.log','output/concurrent-local/refactored-quality.log','output/concurrent-local/acceptance-format-check.log'];const report={date:'2026-10-28',status:'Performed bounded local verification on committed runtime; final publication audited separately before goal completion',candidate,requirement:'REQ-036',plan:'VER-036',specification:{path:root+'concurrent-local-specification.json',sha256:hash(root+'concurrent-local-specification.json')},criteria,gates:{unit:720,browser:219,workbenchOriginalScreenshots:18,finalUnitCommand:'npm test',finalFollowOnCommand:'npm run test:ui && npm run workbench:check && npm run quality',finalFollowOnExit:0,formatTypesLint:'passed',unchangedQualityThresholds:true,qualityWorkerRefactor:'Initial combined run passed all behavioral checks but failed the new monolithic worker complexity. Split worker;720 units and complete219 browser/workbench/quality rerun pass. Production source unchanged by the worker-only refactor.',logs:sources.map(path=>({path,sha256:hash(path)}))},preservationAtExecution:preservation.preservation,limits:['Local trusted-process SQLite proof only; REQ-025 future authentication/backend obligation unchanged.','Declared actual and connected synthetic populations, one run per adversarial scenario and sampled RSS; not arbitrary scale, continuous memory peak or hardware-independent SLA.','Synthetic domain attestations are lifecycle-contract proof, not representative-human/scientific/physical validation.','Existing cap rejects page25; all56 page1 receipts still exhausted. Query counts are driver-call/returned-row observations, not scan complexity bounds.','Already-open read transactions avoid writer reservation; startup migration/index checks can still contend and return busy. No migrations or additional adapters introduced.'],finalPublication:'A separate final audit must confirm guarded status publication, complete backup, restored command ledgers/export and exact code fingerprints before goal completion.'};writeFileSync(root+'concurrent-local-verification-execution.json',await prettier.format(JSON.stringify(report),{...await prettier.resolveConfig(root+'concurrent-local-verification-execution.json'),parser:'json'}),{flag:'wx'});console.log(JSON.stringify({candidate,criteria:criteria.length,gates:report.gates.unit,browser:report.gates.browser}));

