 const actual=new DatabaseSync('projects/tracer/tracer.sqlite',{readOnly:true}),recovered=new DatabaseSync(destination,{readOnly:true}),initial=new DatabaseSync(original,{readOnly:true});const tables=[];try{const rows=(db,table)=>db.prepare('SELECT * FROM "'+table.replaceAll('"','""')+'"').all().map(row=>JSON.stringify(row)).sort();for(const {name}of actual.prepare("SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name").all()){const liveRows=rows(actual,name),restoredRows=rows(recovered,name);assert.deepEqual(restoredRows,liveRows,name);tables.push({name,count:liveRows.length,sha256:createHash('sha256').update(JSON.stringify(liveRows)).digest('hex')});}for(const table of['object_revisions','changesets','evidence','changeset_commands','evaluation_commands','resource_identities','configurations','baselines']){const current=new Set(rows(actual,table));for(const row of rows(initial,table))assert.ok(current.has(row),table);}assert.equal(actual.prepare('SELECT version FROM storage_version').get().version,11);}finally{actual.close();recovered.close();initial.close();}
